// minecraft.lua
static const char kLuaFxSrc_minecraft[] =
  "-- minecraft.lua - a blocky world with a full day/night cycle in one minute.\n"
  "--\n"
  "-- 128x64 divides into 32 x 16 blocks of 4 px, which is the largest block size\n"
  "-- that still leaves room for a skyline. Everything is filled rects: on a panel\n"
  "-- this coarse, outlines read as noise and solid colour reads as a world.\n"
  "\n"
  "local W, H = px.size()\n"
  "local B    = 4                       -- block size, px\n"
  "local COLS, ROWS = W // B, H // B    -- 32 x 16\n"
  "local floor, sin, cos, pi, max, min = math.floor, math.sin, math.cos, math.pi, math.max, math.min\n"
  "\n"
  "-- ---------------------------------------------------------------- palette\n"
  "local GRASS_T = {124, 179, 66}   -- lit grass top\n"
  "local GRASS_S = {94, 140, 50}    -- grass side, shaded\n"
  "local DIRT    = {134, 96, 67}\n"
  "local STONE   = {122, 122, 122}\n"
  "local STONE_D = {90, 90, 90}\n"
  "local ORE     = {180, 180, 190}\n"
  "local LOG     = {102, 76, 46}\n"
  "local LEAF    = {60, 120, 45}\n"
  "local LEAF_L  = {80, 148, 58}\n"
  "local WATER   = {50, 110, 220}\n"
  "local SAND    = {214, 200, 148}\n"
  "local TORCH   = {255, 190, 70}\n"
  "\n"
  "local function blk(cx, cy, c, shade)\n"
  "  if cy < 0 or cy >= ROWS then return end\n"
  "  local s = shade or 1.0\n"
  "  px.rect(cx * B, cy * B, B, B,\n"
  "          floor(c[1] * s), floor(c[2] * s), floor(c[3] * s), true)\n"
  "end\n"
  "\n"
  "-- ---------------------------------------------------------------- terrain\n"
  "-- Fixed, not generated per frame: the world should not shimmer.\n"
  "local ground, kind = {}, {}\n"
  "for x = 0, COLS - 1 do\n"
  "  local h = 10 + floor(1.6 * sin(x * 0.42) + 1.2 * sin(x * 0.17 + 1.3))\n"
  "  ground[x] = h\n"
  "  kind[x] = \"grass\"\n"
  "end\n"
  "-- A lake, carved flat.\n"
  "for x = 19, 24 do ground[x] = 12; kind[x] = \"water\" end\n"
  "for _, x in ipairs({18, 25}) do kind[x] = \"sand\" end\n"
  "\n"
  "local trees = { {x = 4, h = 3}, {x = 9, h = 4}, {x = 29, h = 3} }\n"
  "local torches = { {x = 14, y = nil}, {x = 27, y = nil} }\n"
  "for _, t in ipairs(torches) do t.y = ground[t.x] - 1 end\n"
  "\n"
  "-- Clouds drift; each is a run of blocks at a fixed altitude.\n"
  "local clouds = { {x = 2, y = 2, w = 5}, {x = 13, y = 1, w = 7}, {x = 24, y = 3, w = 4} }\n"
  "\n"
  "-- ---------------------------------------------------------------- sky\n"
  "local function mix(a, b, t)\n"
  "  t = max(0, min(1, t))\n"
  "  return {a[1] + (b[1]-a[1])*t, a[2] + (b[2]-a[2])*t, a[3] + (b[3]-a[3])*t}\n"
  "end\n"
  "\n"
  "local NIGHT = {8, 12, 34}\n"
  "local DAWN  = {232, 120, 70}\n"
  "local DAY   = {110, 168, 255}\n"
  "\n"
  "local function sky_colour(t)\n"
  "  -- t is the phase of the whole day. Dawn near 0, noon at .25, dusk at .5.\n"
  "  if t < 0.08 then return mix(NIGHT, DAWN, t / 0.08)\n"
  "  elseif t < 0.20 then return mix(DAWN, DAY, (t - 0.08) / 0.12)\n"
  "  elseif t < 0.45 then return DAY\n"
  "  elseif t < 0.55 then return mix(DAY, DAWN, (t - 0.45) / 0.10)\n"
  "  elseif t < 0.65 then return mix(DAWN, NIGHT, (t - 0.55) / 0.10)\n"
  "  else return NIGHT end\n"
  "end\n"
  "\n"
  "-- Stars sit at fixed points and only fade, which reads as depth; moving ones\n"
  "-- would read as noise at this size.\n"
  "local stars = {}\n"
  "for i = 1, 34 do stars[i] = {x = (i * 41) % W, y = (i * 23) % 30} end\n"
  "\n"
  "-- ---------------------------------------------------------------- draw\n"
  "function draw()\n"
  "  local t   = px.t()\n"
  "  local sky = sky_colour(t)\n"
  "  local day = (t > 0.10 and t < 0.55) and 1.0 or 0.0\n"
  "  local dark = 1.0 - max(0, min(1, (sky[1] + sky[2] + sky[3]) / 420))  -- 0 day .. ~1 night\n"
  "\n"
  "  px.clear(floor(sky[1]), floor(sky[2]), floor(sky[3]))\n"
  "\n"
  "  -- stars, only once the sky is dark enough to hold them\n"
  "  if dark > 0.35 then\n"
  "    local a = (dark - 0.35) / 0.65\n"
  "    for i, s in ipairs(stars) do\n"
  "      local tw = 0.55 + 0.45 * sin(2*pi*(t*6 + i*0.13))\n"
  "      local v = floor(210 * a * tw)\n"
  "      px.pixel(s.x, s.y, v, v, floor(v * 1.05))\n"
  "    end\n"
  "  end\n"
  "\n"
  "  -- sun and moon on the same arc, half a day apart\n"
  "  local function body(phase, rad, c1, c2)\n"
  "    if phase < 0 or phase > 1 then return end\n"
  "    local ax = floor(4 + (W - 8) * phase)\n"
  "    local ay = floor(H * 0.62 - (H * 0.52) * sin(pi * phase))\n"
  "    px.circle(ax, ay, rad + 2, c2[1], c2[2], c2[3], true)\n"
  "    px.circle(ax, ay, rad,     c1[1], c1[2], c1[3], true)\n"
  "  end\n"
  "  body((t - 0.02) / 0.56, 5, {255, 240, 150}, {255, 170, 60})          -- sun\n"
  "  local mp = t < 0.5 and (t + 0.5) or (t - 0.5)\n"
  "  if t > 0.58 or t < 0.06 then body((mp - 0.02) / 0.56, 4, {235,235,245}, {90,95,120}) end\n"
  "\n"
  "  -- clouds, brighter by day\n"
  "  local cs = 0.45 + 0.55 * (1 - dark)\n"
  "  for _, c in ipairs(clouds) do\n"
  "    local cx = floor(c.x + t * COLS * 1.5) % (COLS + c.w) - c.w\n"
  "    for i = 0, c.w - 1 do\n"
  "      blk(cx + i, c.y, {245, 248, 255}, cs)\n"
  "      if i > 0 and i < c.w - 1 then blk(cx + i, c.y + 1, {225, 232, 245}, cs) end\n"
  "    end\n"
  "  end\n"
  "\n"
  "  -- world lighting: blocks dim at night but never go black\n"
  "  local lit = 0.42 + 0.58 * (1 - dark)\n"
  "\n"
  "  for x = 0, COLS - 1 do\n"
  "    local g = ground[x]\n"
  "    if kind[x] == \"water\" then\n"
  "      -- a surface that ripples by one pixel, not by a whole block\n"
  "      local wob = floor(1.5 + 1.5 * sin(2*pi*(t*8) + x))\n"
  "      px.rect(x*B, g*B + wob, B, (ROWS - g)*B - wob,\n"
  "              floor(WATER[1]*lit), floor(WATER[2]*lit), floor(WATER[3]*lit), true)\n"
  "      px.rect(x*B, g*B + wob, B, 1, floor(150*lit), floor(200*lit), 255, true)\n"
  "    else\n"
  "      local top = (kind[x] == \"sand\") and SAND or GRASS_T\n"
  "      blk(x, g, top, lit)\n"
  "      blk(x, g, kind[x] == \"sand\" and SAND or GRASS_S, lit * 0.82)\n"
  "      blk(x, g, top, lit)                                  -- top face, redrawn lit\n"
  "      px.rect(x*B, g*B, B, 1, floor(top[1]*lit*1.15), floor(top[2]*lit*1.15), floor(top[3]*lit*1.15), true)\n"
  "      for y = g + 1, ROWS - 1 do\n"
  "        local c = (y < g + 3) and DIRT or ((x * 7 + y * 13) % 17 == 0 and ORE or\n"
  "                  (((x + y) % 5 == 0) and STONE_D or STONE))\n"
  "        blk(x, y, c, lit)\n"
  "      end\n"
  "    end\n"
  "  end\n"
  "\n"
  "  -- trees\n"
  "  for _, tr in ipairs(trees) do\n"
  "    local base = ground[tr.x]\n"
  "    for i = 1, tr.h do blk(tr.x, base - i, LOG, lit) end\n"
  "    local ty = base - tr.h\n"
  "    for dx = -1, 1 do for dy = 0, 1 do\n"
  "      blk(tr.x + dx, ty - dy, (dx == 0 and dy == 1) and LEAF_L or LEAF, lit)\n"
  "    end end\n"
  "    blk(tr.x - 2, ty, LEAF, lit * 0.9); blk(tr.x + 2, ty, LEAF, lit * 0.9)\n"
  "  end\n"
  "\n"
  "  -- torches: dim by day, and they pool light on the ground at night\n"
  "  for _, tq in ipairs(torches) do\n"
  "    local flick = 0.75 + 0.25 * sin(2*pi*(t*23 + tq.x))\n"
  "    local glow = dark * flick\n"
  "    if glow > 0.05 then\n"
  "      -- One additive lamp, not a stack of filled circles: px.circle overwrites,\n"
  "      -- so a dim colour paints a dark blot instead of a faint light.\n"
  "      px.glow(tq.x*B + 2, tq.y*B + 1, 11 + 2*flick, 255, 165, 55, 0.85 * glow)\n"
  "    end\n"
  "    px.rect(tq.x*B + 1, tq.y*B + 1, 2, 3, 92, 66, 40, true)\n"
  "    px.rect(tq.x*B + 1, tq.y*B, 2, 2,\n"
  "            floor(255*flick), floor(190*flick), floor(70*flick), true)\n"
  "  end\n"
  "\n"
  "  -- a creeper, pacing the flat ground left of the lake\n"
  "  local cx = 11 + floor(6 * (0.5 + 0.5 * sin(2*pi*t)))\n"
  "  local cy = ground[cx] - 2\n"
  "  local bob = (floor(t * 60) % 2 == 0) and 0 or 1\n"
  "  blk(cx, cy + 1, {70, 160, 72}, lit)          -- body\n"
  "  blk(cx, cy, {84, 180, 84}, lit)              -- head\n"
  "  px.rect(cx*B + 1, cy*B + 1, 1, 1, 12, 12, 12, true)\n"
  "  px.rect(cx*B + 3, cy*B + 1, 1, 1, 12, 12, 12, true)\n"
  "  px.rect(cx*B + 1, cy*B + 2, 3, 2, 12, 12, 12, true)\n"
  "  px.rect(cx*B, (cy+2)*B, 2, 2 - bob, floor(60*lit), floor(140*lit), floor(62*lit), true)\n"
  "  px.rect(cx*B + 2, (cy+2)*B, 2, 1 + bob, floor(60*lit), floor(140*lit), floor(62*lit), true)\n"
  "\n"
  "  -- clock, top right, in the sky's contrast\n"
  "  local n = px.now()\n"
  "  local hhmm = string.format(\"%02d:%02d\", n.hour, n.min)\n"
  "  local tv = dark > 0.5 and 235 or 30\n"
  "  px.text(W - px.width(hhmm) - 2, 2, hhmm, tv, tv, tv)\n"
  "end\n";

// room_radar.lua
static const char kLuaFxSrc_room_radar[] =
  "-- room_radar.lua - who is in the room, as a 24 GHz radar sees it.\n"
  "--\n"
  "-- The HLK-LD2450 reports up to three people, each as X and Y in millimetres\n"
  "-- plus a speed, ten times a second, inside a fan 6 m deep and 60 degrees either\n"
  "-- side. This draws exactly that fan up from the middle of the bottom edge, so\n"
  "-- the picture is the sensor's own view of the room: 10 px to the metre.\n"
  "--\n"
  "-- The people are scripted. fake_targets() returns what the radar would, a list\n"
  "-- of {x, y, speed} in mm and cm/s, and on the panel it is the one function to\n"
  "-- replace. The trails read the script's paths directly; on the panel they need\n"
  "-- a short history per target slot instead.\n"
  "--\n"
  "-- Memory is two 128-byte strings per row for the precomputed grid, about 17 KB,\n"
  "-- not a table per pixel: the firmware's Lua heap has to share PSRAM with the\n"
  "-- HUB75 driver.\n"
  "\n"
  "local W, H = px.size()\n"
  "local floor, min, max, abs = math.floor, math.min, math.max, math.abs\n"
  "local sin, cos, sqrt, atan, exp, pi =\n"
  "  math.sin, math.cos, math.sqrt, math.atan, math.exp, math.pi\n"
  "local deg, rad = math.deg, math.rad\n"
  "local fmt, byte, char = string.format, string.byte, string.char\n"
  "\n"
  "local STORY  = 24.0            -- seconds the scripted scene lasts; px.t() spans it\n"
  "PERIOD = STORY                 -- a global: the panel's px.t() spans PERIOD seconds (default 60)\n"
  "local CX, CY = 63.5, 63.0      -- the sensor\n"
  "local PPM    = 10              -- pixels per metre\n"
  "local RANGE, HALF = 6.0, 60    -- metres, and degrees either side\n"
  "\n"
  "-- The beam is decoration: the LD2450 does not sweep. It is what makes a fan of\n"
  "-- dots read as a radar, so it stays, and it stays dim.\n"
  "local SWEEP_T = 4.0            -- there and back; STORY holds a whole number of them\n"
  "local SWEEP_A = 58             -- degrees it reaches either side\n"
  "local PERSIST = 0.45           -- seconds for the phosphor to fade to 1/e\n"
  "\n"
  "local function in_fan(x, y)\n"
  "  return y > 0 and x * x + y * y <= RANGE * RANGE and abs(deg(atan(x, y))) <= HALF\n"
  "end\n"
  "\n"
  "local function to_px(x, y) return CX + x * PPM, CY - y * PPM end\n"
  "\n"
  "-- ---------------------------------------------------------------- the grid\n"
  "-- For every pixel: how lit its ring or spoke is, and at which phase of the\n"
  "-- swing the beam crosses it. Both are fixed, so both are computed once.\n"
  "local GRID, PHASE, X0, X1 = {}, {}, {}, {}\n"
  "do\n"
  "  local SPOKES = {-60, -30, 0, 30, 60}\n"
  "  for y = 0, H - 1 do\n"
  "    local g, p, first, last = {}, {}, nil, nil\n"
  "    for x = 0, W - 1 do\n"
  "      local mx, my = (x + 0.5 - CX) / PPM, (CY - (y + 0.5)) / PPM\n"
  "      local r, ang = sqrt(mx * mx + my * my), deg(atan(mx, my))\n"
  "      local v, ph = 0, 0\n"
  "      if my > 0 and r <= RANGE + 0.08 and abs(ang) <= HALF + 0.8 then\n"
  "        local lit = 0\n"
  "        for k = 1, 6 do                                -- a ring every metre\n"
  "          local d = abs(r - k) * PPM\n"
  "          if d < 1 then lit = max(lit, (1 - d) * ((k % 3 == 0) and 1.0 or 0.5)) end\n"
  "        end\n"
  "        for _, a in ipairs(SPOKES) do                  -- dotted spokes, solid edges\n"
  "          local ar = rad(a)\n"
  "          local d = abs(mx * cos(ar) - my * sin(ar)) * PPM\n"
  "          local edge = abs(a) == HALF\n"
  "          if d < 1 and (edge or floor(r * PPM) % 3 == 0) then\n"
  "            lit = max(lit, (1 - d) * (edge and 0.75 or 0.4))\n"
  "          end\n"
  "        end\n"
  "        v  = 1 + floor(lit * 254)\n"
  "        ph = floor((max(-1, min(1, ang / SWEEP_A)) + 1) / 2 * 255 + 0.5)\n"
  "        first = first or x; last = x\n"
  "      end\n"
  "      g[#g + 1], p[#p + 1] = char(v), char(ph)\n"
  "    end\n"
  "    GRID[y], PHASE[y], X0[y], X1[y] = table.concat(g), table.concat(p), first, last\n"
  "  end\n"
  "end\n"
  "\n"
  "-- The beam swings at constant speed, out and back, so it crosses a pixel at two\n"
  "-- points of each swing; time since the later one is the phosphor's age. A sine\n"
  "-- swing was tried first: it dwells at the edges and burns a bright band there.\n"
  "local function background(S, g)\n"
  "  local u = (S / SWEEP_T) % 1\n"
  "  for y = 0, H - 1 do\n"
  "    local x0 = X0[y]\n"
  "    if x0 then\n"
  "      local grid, phase = GRID[y], PHASE[y]\n"
  "      for x = x0, X1[y] do\n"
  "        local v = byte(grid, x + 1)\n"
  "        if v > 0 then\n"
  "          local q = byte(phase, x + 1) / 255 * 2 - 1\n"
  "          local since = min((u - (q + 1) / 4) % 1, (u - (3 - q) / 4) % 1) * SWEEP_T\n"
  "          local beam = 0.5 * exp(-since / PERSIST) + 0.7 * exp(-since / 0.05)\n"
  "          local lit = (v - 1) / 254\n"
  "          px.pixel(x, y, min(255, floor((5 + lit * 30 + beam * 12) * g)),\n"
  "                         min(255, floor((14 + lit * 140 + beam * 95) * g)),\n"
  "                         min(255, floor((11 + lit * 105 + beam * 70) * g)))\n"
  "        end\n"
  "      end\n"
  "    end\n"
  "  end\n"
  "end\n"
  "\n"
  "-- ---------------------------------------------------------------- the people\n"
  "-- Waypoints {seconds, x metres, y metres}. Absent outside the first and last.\n"
  "-- A repeated position is someone sitting down.\n"
  "local PEOPLE = {\n"
  "  { col = { 40, 235, 255}, seed = 0.0, path = {\n"
  "      {1.0, 3.8, 2.2}, {4.5, 1.2, 3.0}, {7.5, -0.9, 2.4}, {9.5, -0.9, 1.4},\n"
  "      {16.5, -0.9, 1.4}, {19.5, -2.4, 1.8}, {21.5, -4.2, 2.3} } },\n"
  "  { col = {255, 175, 40}, seed = 1.7, path = {\n"
  "      {5.5, 0.6, 6.6}, {9.0, 1.6, 4.2}, {14.5, 1.6, 4.2}, {17.5, 0.3, 2.6},\n"
  "      {20.0, 1.4, 1.6}, {22.5, 3.6, 1.9} } },\n"
  "  { col = {245, 80, 210}, seed = 3.1, path = {\n"
  "      {11.5, -5.4, 3.6}, {18.5, 5.2, 3.0} } },\n"
  "}\n"
  "\n"
  "local function pos(person, s)\n"
  "  local p = person.path\n"
  "  s = s % STORY\n"
  "  if s < p[1][1] or s > p[#p][1] then return nil end\n"
  "  for i = 1, #p - 1 do\n"
  "    local a, b = p[i], p[i + 1]\n"
  "    if s <= b[1] then\n"
  "      local f = (s - a[1]) / (b[1] - a[1])\n"
  "      -- The radar's own wobble: centimetres, slow enough not to read as walking.\n"
  "      local j = person.seed\n"
  "      return a[2] + (b[2] - a[2]) * f + 0.05 * sin(s * 1.3 + j),\n"
  "             a[3] + (b[3] - a[3]) * f + 0.05 * sin(s * 0.9 + 2 * j)\n"
  "    end\n"
  "  end\n"
  "end\n"
  "\n"
  "local function visible(person, s)\n"
  "  local x, y = pos(person, s)\n"
  "  return x ~= nil and in_fan(x, y)\n"
  "end\n"
  "\n"
  "-- What the LD2450 hands over: up to three {x, y, speed} in mm and cm/s, in\n"
  "-- slots. On the panel this is the one function to replace.\n"
  "local function fake_targets(s)\n"
  "  local out = {}\n"
  "  for i, person in ipairs(PEOPLE) do\n"
  "    local x, y = pos(person, s)\n"
  "    if x and in_fan(x, y) then\n"
  "      local xp, yp = pos(person, s - 0.1)\n"
  "      local speed = xp and sqrt((x - xp) ^ 2 + (y - yp) ^ 2) * 1000 or 0\n"
  "      out[#out + 1] = {x = floor(x * 1000), y = floor(y * 1000), speed = floor(speed), slot = i}\n"
  "    end\n"
  "  end\n"
  "  return out\n"
  "end\n"
  "\n"
  "-- ---------------------------------------------------------------- the words\n"
  "local DIG = {\n"
  "  [\"0\"]={\".####.\",\"######\",\"##..##\",\"##..##\",\"##..##\",\"##..##\",\"##..##\",\"##..##\",\"##..##\",\"######\",\".####.\"},\n"
  "  [\"1\"]={\"..##..\",\".###..\",\"####..\",\"..##..\",\"..##..\",\"..##..\",\"..##..\",\"..##..\",\"..##..\",\"######\",\"######\"},\n"
  "  [\"2\"]={\".####.\",\"######\",\"##..##\",\"....##\",\"...###\",\"..###.\",\".###..\",\"###...\",\"##....\",\"######\",\"######\"},\n"
  "  [\"3\"]={\".####.\",\"######\",\"##..##\",\"....##\",\"..###.\",\"..####\",\"....##\",\"....##\",\"##..##\",\"######\",\".####.\"},\n"
  "}\n"
  "\n"
  "local function big(x, y, s, r, g, b)\n"
  "  local gl = DIG[s]\n"
  "  if not gl then return end\n"
  "  for row = 1, #gl do\n"
  "    for col = 1, 6 do\n"
  "      if gl[row]:sub(col, col) == \"#\" then px.pixel(x + col - 1, y + row - 1, r, g, b) end\n"
  "    end\n"
  "  end\n"
  "end\n"
  "\n"
  "local function dim(c, k) return floor(c[1] * k), floor(c[2] * k), floor(c[3] * k) end\n"
  "\n"
  "-- ---------------------------------------------------------------- draw\n"
  "function draw()\n"
  "  local S = px.t() * STORY\n"
  "  local targets = fake_targets(S)\n"
  "\n"
  "  -- An empty room fades down after a moment: the sleep idea, drawn.\n"
  "  local seen = 0\n"
  "  for k = 0, 4 do\n"
  "    if #fake_targets(S - k * 0.3) > 0 then seen = seen + 1 end\n"
  "  end\n"
  "  local g = 0.3 + 0.7 * seen / 5\n"
  "\n"
  "  px.clear(0, 0, 0)\n"
  "  background(S, g)\n"
  "\n"
  "  local TEAL = {0, 150, 115}\n"
  "  for _, k in ipairs({2, 4, 6}) do\n"
  "    local label = k .. \"M\"\n"
  "    local lx = min(W - px.width(label), floor(CX + k * PPM * sin(rad(HALF)) + 4))\n"
  "    local ly = floor(CY - k * PPM * cos(rad(HALF)) - 5)\n"
  "    px.text(lx, ly, label, dim(TEAL, 0.8 * g))\n"
  "  end\n"
  "\n"
  "  local near\n"
  "  for _, t in ipairs(targets) do\n"
  "    local person = PEOPLE[t.slot]\n"
  "    local col = person.col\n"
  "    local mx, my = t.x / 1000, t.y / 1000\n"
  "    local bx, by = to_px(mx, my)\n"
  "    local ix, iy = floor(bx), floor(by)\n"
  "    local d = sqrt(mx * mx + my * my)\n"
  "    near = near and min(near, d) or d\n"
  "\n"
  "    -- trail, sampled at the radar's own 10 Hz\n"
  "    for k = 1, 14 do\n"
  "      local x, y = pos(person, S - k * 0.1)\n"
  "      if x and in_fan(x, y) then\n"
  "        local tx, ty = to_px(x, y)\n"
  "        px.blend(floor(tx), floor(ty), col[1], col[2], col[3], 0.75 * (1 - k / 15))\n"
  "      end\n"
  "    end\n"
  "\n"
  "    -- just walked in: a burst of light where the radar first saw them\n"
  "    local age = 1.0\n"
  "    for k = 1, 10 do\n"
  "      if not visible(person, S - k * 0.1) then age = (k - 1) * 0.1; break end\n"
  "    end\n"
  "    if age < 1.0 then px.glow(bx, by, 3 + 14 * age, col[1], col[2], col[3], 0.8 * (1 - age)) end\n"
  "\n"
  "    if t.speed > 12 then\n"
  "      px.glow(bx, by, 5, col[1], col[2], col[3], 0.9)\n"
  "    else\n"
  "      -- sitting still: a slow ring, so a person who does not move is not\n"
  "      -- mistaken for a dead pixel\n"
  "      local f = (S / 1.6 + t.slot * 0.3) % 1\n"
  "      local rr = 2 + 6 * f\n"
  "      for a = 0, 35 do\n"
  "        px.blend(floor(bx + rr * cos(a * pi / 18)), floor(by + rr * sin(a * pi / 18)),\n"
  "                 col[1], col[2], col[3], 0.7 * (1 - f))\n"
  "      end\n"
  "      px.glow(bx, by, 4, col[1], col[2], col[3], 0.6)\n"
  "    end\n"
  "    px.rect(ix - 1, iy - 1, 2, 2, (col[1] + 255) // 2, (col[2] + 255) // 2, (col[3] + 255) // 2, true)\n"
  "\n"
  "    local label = fmt(\"%.1fM\", d)\n"
  "    px.text(min(W - px.width(label) - 1, ix + 4), max(0, iy - 9), label, dim(col, 0.85))\n"
  "  end\n"
  "\n"
  "  px.text(1, 1, \"ROOM RADAR\", dim(TEAL, g))\n"
  "  local n = #targets\n"
  "  local white = floor(255 * g)\n"
  "  -- Picopixel's glyphs start two rows below y, so 56 is the last row that fits.\n"
  "  big(2, 51, tostring(n), white, white, white)\n"
  "  if n == 0 then\n"
  "    px.text(10, 50, \"EMPTY\", dim(TEAL, g))\n"
  "  else\n"
  "    px.text(10, 50, \"IN ROOM\", dim(TEAL, g))\n"
  "    px.text(10, 56, fmt(\"NEAR %.1fM\", near), dim(TEAL, g))\n"
  "  end\n"
  "\n"
  "  local now = px.now()\n"
  "  local hhmm = fmt(\"%02d:%02d\", now.hour, now.min)\n"
  "  px.text(W - px.width(hhmm) - 1, 56, hhmm, white, white, white)\n"
  "  px.text(W - px.width(\"LD2450\") - 1, 50, \"LD2450\", dim(TEAL, 0.7 * g))\n"
  "end\n";

// snake_clock.lua
static const char kLuaFxSrc_snake_clock[] =
  "-- snake_clock.lua - HH:MM where each digit is a snake.\n"
  "--\n"
  "-- On the minute the four snakes crawl away downward and four new ones crawl in\n"
  "-- from the top and lay themselves out as the next time.\n"
  "--\n"
  "-- The model is a rope, not falling blocks. A digit's cells are ordered into a\n"
  "-- walk; the snake's body is that whole walk, and the animation slides the body\n"
  "-- along a route. Dissolve routes the walk into a column heading off the bottom;\n"
  "-- assembly routes a column from above into the walk. At rest the body sits\n"
  "-- exactly on the digit, which is why the still frame is a clean clock and not\n"
  "-- an approximation of one.\n"
  "\n"
  "local W, H = px.size()\n"
  "local B = 4\n"
  "local COLS, ROWS = W // B, H // B\n"
  "local floor, min, max, abs, sin, pi = math.floor, math.min, math.max, math.abs, math.sin, math.pi\n"
  "\n"
  "local GLYPH = {\n"
  "  [\"0\"]={\"01110\",\"10001\",\"10011\",\"10101\",\"11001\",\"10001\",\"01110\"},\n"
  "  [\"1\"]={\"00100\",\"01100\",\"00100\",\"00100\",\"00100\",\"00100\",\"01110\"},\n"
  "  [\"2\"]={\"01110\",\"10001\",\"00001\",\"00010\",\"00100\",\"01000\",\"11111\"},\n"
  "  [\"3\"]={\"11110\",\"00001\",\"00001\",\"01110\",\"00001\",\"00001\",\"11110\"},\n"
  "  [\"4\"]={\"00010\",\"00110\",\"01010\",\"10010\",\"11111\",\"00010\",\"00010\"},\n"
  "  [\"5\"]={\"11111\",\"10000\",\"11110\",\"00001\",\"00001\",\"10001\",\"01110\"},\n"
  "  [\"6\"]={\"00110\",\"01000\",\"10000\",\"11110\",\"10001\",\"10001\",\"01110\"},\n"
  "  [\"7\"]={\"11111\",\"00001\",\"00010\",\"00100\",\"01000\",\"01000\",\"01000\"},\n"
  "  [\"8\"]={\"01110\",\"10001\",\"10001\",\"01110\",\"10001\",\"10001\",\"01110\"},\n"
  "  [\"9\"]={\"01110\",\"10001\",\"10001\",\"01111\",\"00001\",\"00010\",\"01100\"},\n"
  "}\n"
  "\n"
  "local TOP, DIGH = 5, 7\n"
  "local XS = {3, 9, 18, 24}\n"
  "local COLON = 15\n"
  "local RUNWAY = ROWS + 6          -- long enough to be fully off-screen at the ends\n"
  "\n"
  "-- One hue per digit position, so a snake keeps its identity across the change.\n"
  "local SNAKE = { {0,225,150}, {255,180,40}, {90,150,255}, {230,80,180} }\n"
  "\n"
  "-- ---------------------------------------------------------------- the walk\n"
  "-- Nearest-neighbour from the top-left cell. On these glyphs almost every step\n"
  "-- lands on a neighbour; the rare jump is one cell wide and reads as the snake\n"
  "-- crossing its own stroke rather than as a break.\n"
  "local function walk_of(ch, x0)\n"
  "  local g = GLYPH[ch]\n"
  "  local cells = {}\n"
  "  for r = 1, DIGH do\n"
  "    local row = g[r]\n"
  "    for c = 1, 5 do\n"
  "      if row:sub(c, c) == \"1\" then cells[#cells+1] = {c = x0 + c - 1, r = TOP + r - 1} end\n"
  "    end\n"
  "  end\n"
  "  local path, used = {}, {}\n"
  "  local cur = 1                                  -- topmost-leftmost, so it enters from above\n"
  "  path[1] = cells[1]; used[1] = true\n"
  "  for _ = 2, #cells do\n"
  "    local best, bd = nil, 1e9\n"
  "    for i, c in ipairs(cells) do\n"
  "      if not used[i] then\n"
  "        local d = abs(c.c - path[#path].c) + abs(c.r - path[#path].r)\n"
  "        if d < bd then bd, best = d, i end\n"
  "      end\n"
  "    end\n"
  "    used[best] = true; path[#path+1] = cells[best]\n"
  "  end\n"
  "  return path\n"
  "end\n"
  "\n"
  "-- Route: a column of length RUNWAY joined to the walk, or the walk joined to a\n"
  "-- column. Body = route[s .. s+N-1], so sliding s animates the whole rope.\n"
  "local function route_in(path)\n"
  "  local head = path[1]\n"
  "  local r = {}\n"
  "  for k = RUNWAY, 1, -1 do r[#r+1] = {c = head.c, r = head.r - k} end\n"
  "  for _, c in ipairs(path) do r[#r+1] = c end\n"
  "  return r, RUNWAY\n"
  "end\n"
  "local function route_out(path)\n"
  "  local tail = path[#path]\n"
  "  local r = {}\n"
  "  for _, c in ipairs(path) do r[#r+1] = c end\n"
  "  for k = 1, RUNWAY do r[#r+1] = {c = tail.c, r = tail.r + k} end\n"
  "  return r\n"
  "end\n"
  "\n"
  "-- ---------------------------------------------------------------- state\n"
  "local shown\n"
  "local walks_cur, walks_new = {}, {}\n"
  "local function set_time(cur, nxt)\n"
  "  if shown == cur then return end\n"
  "  shown = cur\n"
  "  local D = {1, 2, 4, 5}\n"
  "  for i = 1, 4 do\n"
  "    walks_cur[i] = walk_of(cur:sub(D[i], D[i]), XS[i])\n"
  "    walks_new[i] = walk_of(nxt:sub(D[i], D[i]), XS[i])\n"
  "  end\n"
  "end\n"
  "\n"
  "-- ---------------------------------------------------------------- drawing\n"
  "local function cell(c, r, col, s)\n"
  "  if r < 0 or r >= ROWS or c < 0 or c >= COLS then return end\n"
  "  s = s or 1.0\n"
  "  px.rect(c*B, r*B, B, B, floor(col[1]*s*0.55), floor(col[2]*s*0.55), floor(col[3]*s*0.55), true)\n"
  "  px.rect(c*B, r*B, B-1, B-1, floor(col[1]*s), floor(col[2]*s), floor(col[3]*s), true)\n"
  "end\n"
  "\n"
  "-- The body is drawn from tail to head so the head sits on top, and it brightens\n"
  "-- along its length: that is what makes a line of blocks read as a creature.\n"
  "--\n"
  "-- A pulse also runs head-to-tail the whole time, not only during a change. A\n"
  "-- clock that is only alive for ten seconds a minute is a still image with an\n"
  "-- interruption; the pulse is what makes the other fifty seconds worth looking\n"
  "-- at, and it costs one sine per cell.\n"
  "local function body(route, s, n, col, headglow, pulse, blink)\n"
  "  for i = 0, n - 1 do\n"
  "    local p = route[s + i + 1]\n"
  "    if p then\n"
  "      local f = i / max(1, n - 1)                 -- 0 tail .. 1 head\n"
  "      local base = 0.52 + 0.38 * f\n"
  "      local wave = 0\n"
  "      if pulse then\n"
  "        -- one crest travelling head-to-tail, narrow enough to read as a beat\n"
  "        local d = abs(((1 - f) - pulse) % 1.0)\n"
  "        d = min(d, 1 - d)\n"
  "        wave = 0.55 * max(0, 1 - d * 7)\n"
  "      end\n"
  "      cell(p.c, p.r, col, min(1.25, base + wave))\n"
  "    end\n"
  "  end\n"
  "  local hp = route[s + n]\n"
  "  if hp and hp.r >= -1 and hp.r < ROWS then\n"
  "    if headglow then px.glow(hp.c*B + 2, hp.r*B + 2, 7, col[1], col[2], col[3], 0.5) end\n"
  "    if not blink then\n"
  "      px.rect(hp.c*B + 1, hp.r*B + 1, 1, 1, 255, 255, 255, true)   -- an eye\n"
  "    end\n"
  "  end\n"
  "end\n"
  "\n"
  "local DIS0, DIS1, ASM1 = 0.50, 0.72, 0.99\n"
  "\n"
  "function draw()\n"
  "  local t = px.t()\n"
  "  local n = px.now()\n"
  "  local cur = string.format(\"%02d:%02d\", n.hour, n.min)\n"
  "  local nxt = string.format(\"%02d:%02d\", (n.min == 59) and (n.hour + 1) % 24 or n.hour,\n"
  "                            (n.min + 1) % 60)\n"
  "  set_time(cur, nxt)\n"
  "\n"
  "  px.clear(5, 7, 12)\n"
  "  for r = 0, ROWS - 1 do px.rect(0, r*B, W, 1, 10, 14, 22, true) end\n"
  "\n"
  "  -- The colon stays: it is punctuation, not a snake. It dims while they travel.\n"
  "  local held = (t < DIS0) and 1.0 or 0.30\n"
  "  local beat = 0.55 + 0.45 * abs(sin(pi * n.sec))\n"
  "  for _, r in ipairs({TOP+1, TOP+2, TOP+4, TOP+5}) do\n"
  "    cell(COLON, r, {225, 232, 245}, beat * held)\n"
  "  end\n"
  "\n"
  "  for i = 1, 4 do\n"
  "    local col = SNAKE[i]\n"
  "    if t < DIS0 then\n"
  "      local p = walks_cur[i]\n"
  "      -- Each snake pulses at its own rate and blinks on its own schedule, so\n"
  "      -- four of them never look like one animation drawn four times.\n"
  "      local pulse = (t * (7 + i * 1.7)) % 1.0\n"
  "      local bl = ((t * 60 + i * 11) % 17) < 0.6\n"
  "      body(route_out(p), 0, #p, col, true, pulse, bl)\n"
  "\n"
  "    elseif t < DIS1 then\n"
  "      -- crawling away: the rope slides forward into its exit column\n"
  "      local k = (t - DIS0) / (DIS1 - DIS0)\n"
  "      local p = walks_cur[i]\n"
  "      local lead = (i - 1) * 0.06                 -- the four leave in turn, not as one\n"
  "      local kk = max(0, min(1, (k - lead) / (1 - lead)))\n"
  "      local r = route_out(p)\n"
  "      body(r, floor(kk * (#r - #p)), #p, col, kk > 0, (t * 9) % 1.0, false)\n"
  "\n"
  "    else\n"
  "      -- crawling in: a column from above unrolls onto the new digit\n"
  "      local k = (t - DIS1) / (ASM1 - DIS1)\n"
  "      local p = walks_new[i]\n"
  "      local lead = (i - 1) * 0.07\n"
  "      local kk = max(0, min(1, (k - lead) / (1 - lead)))\n"
  "      local r, rest = route_in(p)\n"
  "      body(r, floor(kk * rest), #p, col, kk < 1, (t * 9) % 1.0, false)\n"
  "    end\n"
  "  end\n"
  "end\n";

// tetris_clock.lua
static const char kLuaFxSrc_tetris_clock[] =
  "-- tetris_clock.lua - HH:MM that clears itself like completed lines and is\n"
  "-- rebuilt by falling tetrominoes when the minute turns.\n"
  "--\n"
  "-- The whole panel is the well: 32 x 16 cells of 4 px. Digits are 5 x 7 cells,\n"
  "-- which is the largest that leaves room above for pieces to fall through.\n"
  "\n"
  "local W, H = px.size()\n"
  "local B = 4\n"
  "local COLS, ROWS = W // B, H // B          -- 32 x 16\n"
  "local floor, ceil, min, max, abs, sin, pi = math.floor, math.ceil, math.min, math.max, math.abs, math.sin, math.pi\n"
  "\n"
  "-- ---------------------------------------------------------------- digits\n"
  "local GLYPH = {\n"
  "  [\"0\"]={\"01110\",\"10001\",\"10011\",\"10101\",\"11001\",\"10001\",\"01110\"},\n"
  "  [\"1\"]={\"00100\",\"01100\",\"00100\",\"00100\",\"00100\",\"00100\",\"01110\"},\n"
  "  [\"2\"]={\"01110\",\"10001\",\"00001\",\"00010\",\"00100\",\"01000\",\"11111\"},\n"
  "  [\"3\"]={\"11110\",\"00001\",\"00001\",\"01110\",\"00001\",\"00001\",\"11110\"},\n"
  "  [\"4\"]={\"00010\",\"00110\",\"01010\",\"10010\",\"11111\",\"00010\",\"00010\"},\n"
  "  [\"5\"]={\"11111\",\"10000\",\"11110\",\"00001\",\"00001\",\"10001\",\"01110\"},\n"
  "  [\"6\"]={\"00110\",\"01000\",\"10000\",\"11110\",\"10001\",\"10001\",\"01110\"},\n"
  "  [\"7\"]={\"11111\",\"00001\",\"00010\",\"00100\",\"01000\",\"01000\",\"01000\"},\n"
  "  [\"8\"]={\"01110\",\"10001\",\"10001\",\"01110\",\"10001\",\"10001\",\"01110\"},\n"
  "  [\"9\"]={\"01110\",\"10001\",\"10001\",\"01111\",\"00001\",\"00010\",\"01100\"},\n"
  "}\n"
  "\n"
  "local TOP   = 5                              -- top row of the digit block\n"
  "local DIGH  = 7\n"
  "local XS    = {3, 9, 18, 24}                 -- left column of each digit\n"
  "local COLON = 15\n"
  "\n"
  "-- Tetromino colours, in the order pieces are handed out.\n"
  "local PIECE_COLS = {\n"
  "  {0,240,240}, {240,240,0}, {160,60,230}, {60,220,80},\n"
  "  {235,60,60}, {60,120,240}, {245,150,40},\n"
  "}\n"
  "\n"
  "-- Cells the time occupies, as a set keyed \"c,r\".\n"
  "local function cells_for(hhmm)\n"
  "  local out = {}\n"
  "  local DPOS = {1, 2, 4, 5}          -- \"HH:MM\" - the colon is position 3\n"
  "  for i = 1, 4 do\n"
  "    local g = GLYPH[hhmm:sub(DPOS[i], DPOS[i])]\n"
  "    local x0 = XS[i]\n"
  "    for r = 1, DIGH do\n"
  "      local row = g[r]\n"
  "      for c = 1, 5 do\n"
  "        if row:sub(c, c) == \"1\" then out[#out+1] = {c = x0 + c - 1, r = TOP + r - 1} end\n"
  "      end\n"
  "    end\n"
  "  end\n"
  "  return out\n"
  "end\n"
  "\n"
  "-- Group cells into pieces of up to four, preferring neighbours, so what falls\n"
  "-- looks like tetrominoes rather than confetti. Bottom rows first: a well fills\n"
  "-- from the floor up, and the eye knows it.\n"
  "-- The colon is not a tetromino and does not fall: it is punctuation, and it\n"
  "-- stays put while the digits come and go.\n"
  "local COLON_CELLS = {{c = COLON, r = TOP+1}, {c = COLON, r = TOP+2},\n"
  "                     {c = COLON, r = TOP+4}, {c = COLON, r = TOP+5}}\n"
  "\n"
  "local function make_pieces(cells)\n"
  "  local occupied, bykey = {}, {}\n"
  "  for _, c in ipairs(cells) do bykey[c.c .. \",\" .. c.r] = c end\n"
  "  table.sort(cells, function(a, b)\n"
  "    if a.r ~= b.r then return a.r > b.r end\n"
  "    return a.c < b.c\n"
  "  end)\n"
  "  local pieces = {}\n"
  "  for _, seed in ipairs(cells) do\n"
  "    local k = seed.c .. \",\" .. seed.r\n"
  "    if not occupied[k] then\n"
  "      local grp = {seed}; occupied[k] = true\n"
  "      -- grow greedily through neighbours\n"
  "      local guard = 0\n"
  "      while #grp < 4 and guard < 24 do\n"
  "        guard = guard + 1\n"
  "        local grew = false\n"
  "        for _, g in ipairs(grp) do\n"
  "          for _, d in ipairs({{1,0},{-1,0},{0,1},{0,-1}}) do\n"
  "            local nk = (g.c+d[1]) .. \",\" .. (g.r+d[2])\n"
  "            if bykey[nk] and not occupied[nk] and #grp < 4 then\n"
  "              occupied[nk] = true; grp[#grp+1] = bykey[nk]; grew = true\n"
  "            end\n"
  "          end\n"
  "        end\n"
  "        if not grew then break end\n"
  "      end\n"
  "      -- Stepping by 3 through seven colours means neighbours never repeat and\n"
  "      -- the whole palette is used before any colour comes round again.\n"
  "      local ci = (#pieces * 3) % #PIECE_COLS + 1\n"
  "      pieces[#pieces+1] = {cells = grp, col = PIECE_COLS[ci]}\n"
  "    end\n"
  "  end\n"
  "  return pieces\n"
  "end\n"
  "\n"
  "-- ---------------------------------------------------------------- state\n"
  "local shown, nextt = nil, nil\n"
  "local pieces_cur, pieces_new = nil, nil\n"
  "\n"
  "local function set_time(cur, nxt)\n"
  "  if shown ~= cur then\n"
  "    shown, nextt = cur, nxt\n"
  "    pieces_cur = make_pieces(cells_for(cur))\n"
  "    pieces_new = make_pieces(cells_for(nxt))\n"
  "  end\n"
  "end\n"
  "\n"
  "-- ---------------------------------------------------------------- drawing\n"
  "local function cell(c, r, col, bright)\n"
  "  if r < 0 or r >= ROWS or c < 0 or c >= COLS then return end\n"
  "  local s = bright or 1.0\n"
  "  local x, y = c * B, r * B\n"
  "  px.rect(x, y, B, B, floor(col[1]*s*0.62), floor(col[2]*s*0.62), floor(col[3]*s*0.62), true)\n"
  "  px.rect(x, y, B-1, B-1, floor(col[1]*s), floor(col[2]*s), floor(col[3]*s), true)\n"
  "  px.rect(x, y, B-1, 1, min(255,floor(col[1]*s*1.5)), min(255,floor(col[2]*s*1.5)),\n"
  "          min(255,floor(col[3]*s*1.5)), true)     -- lit top edge\n"
  "end\n"
  "\n"
  "local function well()\n"
  "  px.clear(6, 8, 14)\n"
  "  for r = 0, ROWS - 1 do                      -- faint grid, so the well reads\n"
  "    px.rect(0, r*B, W, 1, 12, 16, 26, true)\n"
  "  end\n"
  "  px.rect(0, 0, 1, H, 22, 28, 44, true)\n"
  "  px.rect(W-1, 0, 1, H, 22, 28, 44, true)\n"
  "end\n"
  "\n"
  "-- ---------------------------------------------------------------- phases\n"
  "-- 0.00-0.62  steady\n"
  "-- 0.62-0.80  line clear, bottom row of the block upwards\n"
  "-- 0.80-1.00  the next time falls into place\n"
  "local CLR0, CLR1, ASM0 = 0.62, 0.80, 0.80\n"
  "\n"
  "function draw()\n"
  "  local t = px.t()\n"
  "  local n = px.now()\n"
  "  local cur = string.format(\"%02d:%02d\", n.hour, n.min)\n"
  "  local nxt = string.format(\"%02d:%02d\", (n.min == 59) and (n.hour + 1) % 24 or n.hour,\n"
  "                            (n.min + 1) % 60)\n"
  "  set_time(cur, nxt)\n"
  "  well()\n"
  "\n"
  "  -- Colon: always there, breathing once a second so the clock reads as running.\n"
  "  local beat = 0.55 + 0.45 * math.abs(sin(pi * n.sec))\n"
  "  for _, c in ipairs(COLON_CELLS) do cell(c.c, c.r, {225, 232, 245}, beat) end\n"
  "\n"
  "  if t < CLR0 then\n"
  "    -- A gloss sweeps across the stack the whole time. A clock that only moves\n"
  "    -- for ten seconds a minute is a still image with an interruption, and the\n"
  "    -- other fifty seconds are most of what anyone actually sees.\n"
  "    -- Two glints half a period apart. One alone spends a quarter of its cycle\n"
  "    -- off the left edge, and those frames are dead - measured, not assumed.\n"
  "    local SPAN = 36\n"
  "    local s1 = ((t * 3.0) % 1.0) * SPAN - 2\n"
  "    local s2 = (((t * 3.0) + 0.5) % 1.0) * SPAN - 2\n"
  "    for _, p in ipairs(pieces_cur) do\n"
  "      for _, c in ipairs(p.cells) do cell(c.c, c.r, p.col) end\n"
  "    end\n"
  "    -- Blended toward white, not multiplied: these colours already sit near 255,\n"
  "    -- so scaling them up clamps and nothing moves. Measured that the hard way.\n"
  "    for _, p in ipairs(pieces_cur) do\n"
  "      for _, c in ipairs(p.cells) do\n"
  "        local k = c.c + c.r * 0.35\n"
  "        local a = 0.5 * max(max(0, 1 - abs(k - s1) / 3.0),\n"
  "                            max(0, 1 - abs(k - s2) / 3.0))\n"
  "        if a > 0.01 then\n"
  "          for yy = 0, B-2 do for xx = 0, B-2 do\n"
  "            px.blend(c.c*B + xx, c.r*B + yy, 255, 255, 255, a)\n"
  "          end end\n"
  "        end\n"
  "      end\n"
  "    end\n"
  "    -- Every few seconds one piece remembers it is a tetromino and settles.\n"
  "    local who = floor(t * 14) % max(1, #pieces_cur) + 1\n"
  "    local ph = (t * 14) % 1.0\n"
  "    if ph < 0.18 and pieces_cur[who] then\n"
  "      local q = pieces_cur[who]\n"
  "      local lift = (ph < 0.09) and 1 or 0\n"
  "      for _, c in ipairs(q.cells) do cell(c.c, c.r - lift, q.col, 1.15) end\n"
  "    end\n"
  "\n"
  "  elseif t < CLR1 then\n"
  "    -- Seven rows go in sequence from the bottom. The row being cleared flares\n"
  "    -- white first, which is the whole pleasure of a line clear.\n"
  "    local k = (t - CLR0) / (CLR1 - CLR0)\n"
  "    local cleared = floor(k * DIGH)                 -- how many rows are gone\n"
  "    local frac = k * DIGH - cleared                 -- progress within this row\n"
  "    local row_going = TOP + DIGH - 1 - cleared\n"
  "    for _, p in ipairs(pieces_cur) do\n"
  "      for _, c in ipairs(p.cells) do\n"
  "        if c.r < row_going then\n"
  "          -- everything above a cleared row drops by that many rows\n"
  "          cell(c.c, c.r + cleared, p.col, 0.92)\n"
  "        elseif c.r == row_going then\n"
  "          local flare = 1.0 - frac\n"
  "          if frac < 0.55 then\n"
  "            cell(c.c, c.r + cleared, {255, 255, 255}, 0.35 + 0.65 * flare)\n"
  "          end\n"
  "        end\n"
  "      end\n"
  "    end\n"
  "    if frac < 0.5 then                              -- flash across the full width\n"
  "      local a = (0.5 - frac) * 0.5\n"
  "      px.rect(0, (row_going + cleared) * B, W, B,\n"
  "              floor(255*a), floor(255*a), floor(255*a), true)\n"
  "    end\n"
  "\n"
  "  else\n"
  "    -- Assemble. Each piece gets a slot in the order make_pieces produced\n"
  "    -- (bottom-up), falls from above the well, and eases into its cells.\n"
  "    local k = (t - ASM0) / (1.0 - ASM0)\n"
  "    local np = #pieces_new\n"
  "    for i, p in ipairs(pieces_new) do\n"
  "      local start = (i - 1) / np * 0.72\n"
  "      local u = (k - start) / 0.28\n"
  "      if u > 0 then\n"
  "        local landed = u >= 1\n"
  "        u = min(1, u)\n"
  "        local ease = 1 - (1 - u) * (1 - u)          -- fast in, settles at the end\n"
  "        local top_r = math.huge\n"
  "        for _, c in ipairs(p.cells) do top_r = min(top_r, c.r) end\n"
  "        local drop = floor((1 - ease) * (top_r + 5))\n"
  "        local squash = (landed and (k - start - 0.28) < 0.05) and 1.35 or 1.0\n"
  "        for _, c in ipairs(p.cells) do\n"
  "          cell(c.c, c.r - drop, p.col, landed and 1.0 or 0.85)\n"
  "        end\n"
  "        if landed and squash > 1 then                -- a flash on the lock\n"
  "          for _, c in ipairs(p.cells) do\n"
  "            px.glow(c.c*B + 2, (c.r)*B + 2, 6, p.col[1], p.col[2], p.col[3], 0.35)\n"
  "          end\n"
  "        end\n"
  "      end\n"
  "    end\n"
  "  end\n"
  "end\n";

static const LuaEffectScript kLuaEffectScripts[LUA_EFFECT_COUNT] = {
  {"minecraft", "MINECRAFT", kLuaFxSrc_minecraft, sizeof(kLuaFxSrc_minecraft) - 1},
  {"room_radar", "ROOM RADAR", kLuaFxSrc_room_radar, sizeof(kLuaFxSrc_room_radar) - 1},
  {"snake_clock", "SNAKE CLOCK", kLuaFxSrc_snake_clock, sizeof(kLuaFxSrc_snake_clock) - 1},
  {"tetris_clock", "TETRIS CLOCK", kLuaFxSrc_tetris_clock, sizeof(kLuaFxSrc_tetris_clock) - 1},
};

#endif  // LUA_EFFECTS_TABLE
